// word-frequency (go entry) -- count 3,000,000 picks from a 64-word
// vocabulary generated by a pinned integer LCG, then fold the counts into one
// deterministic checksum.
//
// Build:  go build -o word-frequency.exe main.go
// Run:    word-frequency.exe
//
// Same workload and same output in every language entry. This is the
// hash-map-shaped task: every pick is a string-keyed lookup + increment, and
// the final fold walks the vocabulary in a fixed order so no language's map
// iteration order can leak into the output.

package main

import "fmt"

const (
	corpus int64 = 3000000
	vocab  int64 = 64
)

func main() {
	words := make([]string, vocab)
	for i := range words {
		words[i] = fmt.Sprintf("word%02d", i)
	}

	counts := make(map[string]int64, 256)

	var state int64 = 1
	for k := int64(0); k < corpus; k++ {
		state = (state * 48271) % 2147483647
		counts[words[state%vocab]]++
	}

	var checksum int64 = 0
	for i := int64(0); i < vocab; i++ {
		checksum = (checksum*31 + counts[words[i]]) % 1000000007
	}
	fmt.Println(checksum)
}
